DBMS.comparisonIndex = [
  {"id":"file-system-vs-database","unit":1,"title":"File-processing system and database system","text":"A file-processing system keeps data in separate files owned by separate programs; a database system keeps it once, under one DBMS that controls access to it. file system dbms advantages vs difference"},
  {"id":"schema-vs-instance","unit":1,"title":"Schema and instance","text":"The schema is the design of the database and rarely changes; the instance is the data stored in it at one moment and changes all the time. intension extension database state structure vs difference"},
  {"id":"data-independence","unit":1,"title":"Physical and logical data independence","text":"Physical data independence hides changes in storage from the logical level; logical data independence hides changes in the logical schema from the views. data independence levels mapping vs difference"},
  {"id":"data-models","unit":1,"title":"Data models: relational, E-R, object-based, semi-structured, hierarchical and network","text":"Each data model describes data, relationships and constraints in its own way: as tables, entities, objects, tagged documents, a tree or a graph. types of data models vs difference"},
  {"id":"two-tier-vs-three-tier","unit":1,"title":"Two-tier and three-tier architecture","text":"In two-tier, the client talks to the database directly; in three-tier, an application server sits between the client and the database. 2-tier 3-tier client server application server vs difference"},
  {"id":"types-of-keys","unit":1,"title":"Super key, candidate key, primary key, alternate key, composite key and foreign key","text":"Every primary key is a candidate key, every candidate key is a super key and a foreign key points to the primary key of another table. keys types superkey candidate primary alternate composite foreign vs difference"},
  {"id":"primary-key-vs-foreign-key","unit":1,"title":"Primary key and foreign key","text":"A primary key identifies each row of its own table; a foreign key in another table refers to that primary key and links the two tables. pk fk primary foreign key referential vs difference"},
  {"id":"primary-key-vs-unique","unit":1,"title":"PRIMARY KEY and UNIQUE constraints","text":"Both stop duplicate values, but a table has only one PRIMARY KEY and it never holds NULL, while it can have many UNIQUE constraints that allow NULL. primary key unique constraint null vs difference"},
  {"id":"entity-vs-referential-integrity","unit":1,"title":"Entity integrity and referential integrity","text":"Entity integrity: a primary key is never NULL. Referential integrity: a foreign key matches a primary key value in the parent table, or is NULL. integrity constraints entity referential foreign key vs difference"},
  {"id":"select-vs-project","unit":1,"title":"Selection (σ) and projection (π)","text":"Selection picks rows that satisfy a condition; projection picks columns and removes duplicate rows. select project sigma pi rows columns relational algebra vs difference"},
  {"id":"relational-algebra-joins","unit":1,"title":"Theta join, equijoin, natural join and outer joins","text":"All joins combine related tuples of two relations; they differ in the condition they use and in what they do with tuples that have no match. join theta equi natural outer left right full relational algebra vs difference"},
  {"id":"relational-algebra-vs-sql","unit":1,"title":"Relational algebra and SQL","text":"Relational algebra is a procedural set of operators on relations used inside the DBMS; SQL is the declarative language that users write. relational algebra sql procedural declarative vs difference"},
  {"id":"ddl-dml-dcl-tcl","unit":1,"title":"DDL, DML, DCL and TCL","text":"DDL defines the structure, DML works on the rows, DCL gives and takes away access rights and TCL ends or undoes transactions. parts of sql commands data definition manipulation control transaction vs difference"},
  {"id":"char-vs-varchar","unit":1,"title":"CHAR and VARCHAR","text":"CHAR(n) always takes n characters, padded with spaces; VARCHAR(n) takes only as many characters as the value needs, up to n. char varchar data types fixed variable length string vs difference"},
  {"id":"ddl-vs-dml","unit":1,"title":"DDL and DML","text":"DDL commands create and change the structure (schema) of the database; DML commands insert, change, delete and read the rows. data definition manipulation language commands vs difference"},
  {"id":"delete-truncate-drop","unit":1,"title":"DELETE, TRUNCATE and DROP","text":"DELETE removes chosen rows and can be rolled back; TRUNCATE quickly removes all rows but keeps the table; DROP removes the table itself. delete truncate drop remove rows table vs difference"},
  {"id":"alter-vs-update","unit":1,"title":"ALTER and UPDATE","text":"ALTER TABLE changes the structure of a table, such as its columns; UPDATE changes the values stored in its rows. alter table update set modify column vs difference"},
  {"id":"strong-vs-weak-entity","unit":2,"title":"Strong and weak entity sets","text":"A strong entity set has a primary key of its own; a weak entity set has only a partial key and depends on an owner entity set. strong weak entity set discriminator partial key identifying relationship vs difference"},
  {"id":"attribute-types","unit":2,"title":"Simple and composite, single-valued and multivalued, stored and derived attributes","text":"Attributes come in pairs: simple or composite (can it be split?), single-valued or multivalued (how many values?) and stored or derived (kept or calculated?). attribute types simple composite multivalued derived stored key e-r vs difference"},
  {"id":"specialization-vs-generalization","unit":2,"title":"Specialization and generalization","text":"Specialization splits one entity set into subclasses (top-down); generalization joins several entity sets into one superclass (bottom-up). Both give the same ISA picture. specialization generalization superclass subclass isa inheritance eer top-down bottom-up vs difference"},
  {"id":"fd-types","unit":2,"title":"Trivial, non-trivial, full, partial and transitive dependencies","text":"A trivial FD says nothing new. A partial FD depends on part of a key. A transitive FD goes through a non-key attribute. functional dependency types trivial full partial transitive fd vs difference"},
  {"id":"fd-vs-mvd","unit":2,"title":"Functional dependency and multivalued dependency","text":"In an FD X → Y, each X value fixes one Y value. In an MVD X →→ Y, each X value fixes a set of Y values, whatever the other attributes are. fd mvd functional multivalued dependency 4nf vs difference"},
  {"id":"lossless-vs-lossy","unit":2,"title":"Lossless and lossy decomposition","text":"A lossless decomposition joins back to exactly the original table; a lossy one gives extra (spurious) rows, so information is lost. lossless lossy non-loss decomposition spurious tuples vs difference"},
  {"id":"1nf-2nf-3nf","unit":2,"title":"1NF, 2NF and 3NF","text":"1NF needs atomic values, 2NF also removes partial dependencies, and 3NF also removes transitive dependencies. first second third normal form 1nf 2nf 3nf partial transitive vs difference"},
  {"id":"lossless-vs-dependency-preservation","unit":2,"title":"Lossless join and dependency preservation","text":"Lossless join is about the data (can we get the table back?); dependency preservation is about the rules (can every FD still be checked in one table?). lossless join dependency preserving decomposition vs difference"},
  {"id":"3nf-vs-bcnf","unit":2,"title":"3NF and BCNF","text":"3NF allows X → A when A is a prime attribute; BCNF does not, so every determinant must be a superkey. third normal form boyce codd bcnf vs difference"},
  {"id":"normal-forms","unit":2,"title":"The normal forms from 1NF to 5NF","text":"Each normal form adds one more condition to the one before it, so each removes one more kind of redundancy. normal forms 1nf 2nf 3nf bcnf 4nf 5nf normalization ladder vs difference"},
  {"id":"set-operations","unit":2,"title":"UNION, UNION ALL, INTERSECT and EXCEPT","text":"All four combine the results of two queries with the same columns. UNION ALL keeps duplicates; the others remove them. set operations union all intersect except minus vs difference"},
  {"id":"count-forms","unit":2,"title":"COUNT(*), COUNT(column) and COUNT(DISTINCT column)","text":"COUNT(*) counts rows; COUNT(column) counts the non-NULL values in a column; COUNT(DISTINCT column) counts the different non-NULL values. count star column distinct aggregate null vs difference"},
  {"id":"where-vs-having","unit":2,"title":"WHERE and HAVING","text":"WHERE filters single rows before they are grouped; HAVING filters whole groups after GROUP BY, so it can use aggregates. where having group by filter rows groups aggregate vs difference"},
  {"id":"group-by-vs-order-by","unit":2,"title":"GROUP BY and ORDER BY","text":"GROUP BY puts rows with the same value into one group and gives one result row per group; ORDER BY only sorts the result rows. group by order by sort groups asc desc vs difference"},
  {"id":"join-types","unit":2,"title":"Inner, outer, cross, natural and self joins","text":"Joins differ in the rows they keep. Inner keeps only matches, outer also keeps unmatched rows of one or both sides, and cross keeps every pair. join types inner left right full outer cross natural self vs difference"},
  {"id":"join-vs-subquery","unit":2,"title":"Join and subquery","text":"A join puts columns of two tables side by side. A subquery is a query inside another query that passes its result outward. join subquery nested query performance vs difference"},
  {"id":"correlated-vs-non-correlated","unit":2,"title":"Correlated and non-correlated subqueries","text":"A non-correlated subquery runs once on its own. A correlated subquery uses a column of the outer query, so it runs again for each outer row. correlated non-correlated nested subquery inner outer vs difference"},
  {"id":"in-vs-exists-any-vs-all","unit":2,"title":"IN and EXISTS, ANY and ALL","text":"IN checks whether a value is in the list a subquery returns, while EXISTS only checks whether the subquery returns any row. ANY needs one value to pass the comparison, while ALL needs every value to pass. in exists not in not exists any all some subquery operators null vs difference"},
  {"id":"table-vs-view","unit":2,"title":"Table, view and materialized view","text":"A table stores rows; a view stores only a query and shows its result when used; a materialized view stores the query's result and must be refreshed. table view virtual table materialized view stored query vs difference"},
  {"id":"trigger-types","unit":2,"title":"BEFORE and AFTER triggers, row-level and statement-level triggers, NEW and OLD","text":"BEFORE triggers run before the change and can fix or reject it; AFTER triggers run once the change is made and suit logging. MySQL triggers are row-level and see the row as NEW and OLD. trigger before after row level statement level for each row new old vs difference"},
  {"id":"serial-vs-concurrent-schedule","unit":3,"title":"Serial and concurrent schedules","text":"A serial schedule runs transactions one after another. A concurrent schedule interleaves them. It is faster, but correct only if it is serializable. serial concurrent non-serial interleaved schedule serializable vs difference"},
  {"id":"recoverable-cascadeless-strict","unit":3,"title":"Recoverable, cascadeless and strict schedules","text":"Each kind is stricter than the one before. Every strict schedule is cascadeless, and every cascadeless schedule is recoverable. recoverable cascadeless strict schedule cascading rollback vs difference"},
  {"id":"conflict-vs-view-serializability","unit":3,"title":"Conflict and view serializability","text":"Conflict serializability looks at the order of conflicting instructions and is easy to test. View serializability looks at reads and final writes. It is wider but hard to test. conflict view serializability precedence graph blind write vs difference"},
  {"id":"concurrency-problems","unit":3,"title":"Lost update, dirty read, unrepeatable read and phantom","text":"Each problem comes from a different conflict. Write-write gives a lost update, write-read a dirty read and read-write an unrepeatable read. Inserts give phantoms. concurrency problems anomalies lost update dirty read unrepeatable non-repeatable phantom incorrect summary vs difference"},
  {"id":"shared-vs-exclusive-lock","unit":3,"title":"Shared and exclusive locks","text":"A shared (S) lock lets many transactions read an item. An exclusive (X) lock lets one transaction read and write it, and keeps everyone else out. shared exclusive lock s x lock-s lock-x read write compatibility vs difference"},
  {"id":"two-phase-locking-types","unit":3,"title":"Basic, strict, rigorous and conservative two phase locking","text":"All four keep a growing and a shrinking phase, so all are serializable. They differ in when locks are taken and released, which decides cascading rollbacks and deadlocks. 2pl two phase locking basic strict rigorous conservative static vs difference"},
  {"id":"deadlock-livelock-starvation","unit":3,"title":"Deadlock, livelock and starvation","text":"In a deadlock, transactions are blocked waiting for each other. In a livelock, they keep running and restarting but never finish. In starvation, one transaction is passed over again and again. deadlock livelock starvation wait-for graph vs difference"},
  {"id":"wait-die-vs-wound-wait","unit":3,"title":"Wait-die and wound-wait","text":"In both schemes the younger transaction is rolled back. In wait-die an older requester waits; in wound-wait an older requester rolls back the younger holder. wait-die wound-wait timestamp deadlock prevention preemptive non-preemptive vs difference"},
  {"id":"deadlock-handling","unit":3,"title":"Deadlock prevention, detection and timeout","text":"Prevention makes a deadlock impossible, detection lets it happen and then breaks it and timeout simply rolls back any transaction that waits too long. deadlock prevention detection recovery timeout wait-for graph avoidance vs difference"},
  {"id":"storage-types","unit":3,"title":"Volatile, non-volatile and stable storage","text":"Volatile storage loses its data in a crash, non-volatile storage survives a crash but not every disk failure and stable storage is built to lose nothing. volatile non-volatile stable storage memory disk crash vs difference"},
  {"id":"recovery-methods","unit":3,"title":"Deferred update, immediate update and shadow paging","text":"Deferred update writes to the database only after commit. Immediate update writes at any time. Shadow paging keeps an old copy of the page table and needs no log. deferred immediate update modification shadow paging log based recovery undo redo vs difference"},
  {"id":"commit-rollback-savepoint","unit":3,"title":"COMMIT, ROLLBACK and ROLLBACK TO SAVEPOINT","text":"COMMIT makes all changes of a transaction permanent; ROLLBACK undoes all of them; ROLLBACK TO SAVEPOINT undoes only the changes made after that savepoint. commit rollback savepoint rollback to release tcl vs difference"},
  {"id":"isolation-levels","unit":3,"title":"READ UNCOMMITTED, READ COMMITTED, REPEATABLE READ and SERIALIZABLE","text":"Each higher isolation level blocks one more problem: dirty reads, then non-repeatable reads, then phantoms. More isolation means less concurrency. isolation levels read uncommitted committed repeatable read serializable dirty phantom vs difference"},
  {"id":"locking-reads-and-lock-tables","unit":3,"title":"SELECT ... FOR SHARE, SELECT ... FOR UPDATE and LOCK TABLES","text":"FOR SHARE takes shared row locks, FOR UPDATE takes exclusive row locks and LOCK TABLES locks whole tables for a session. for share for update lock in share mode lock tables unlock row lock table lock vs difference"},
  {"id":"backup-types","unit":3,"title":"Full, incremental and differential backups","text":"A full backup copies everything; an incremental backup copies changes since the last backup of any kind; a differential backup copies changes since the last full backup. backup full incremental differential restore vs difference"},
  {"id":"dcl-vs-tcl","unit":3,"title":"DCL and TCL","text":"DCL decides who may use which data (GRANT, REVOKE); TCL decides when changes become permanent or are undone (COMMIT, ROLLBACK, SAVEPOINT). dcl tcl data control transaction control language grant revoke commit rollback vs difference"},
  {"id":"grant-vs-revoke","unit":3,"title":"GRANT and REVOKE","text":"GRANT gives a user privileges on database objects; REVOKE takes them back. grant revoke privileges dcl with grant option vs difference"},
  {"id":"raid-levels","unit":4,"title":"RAID levels 0 to 6","text":"The RAID levels differ in how they use striping, mirroring and parity, which decides their speed, cost and how many disk failures they survive. raid 0 1 2 3 4 5 6 levels striping mirroring parity vs difference"},
  {"id":"striping-mirroring-parity","unit":4,"title":"Striping, mirroring and parity","text":"Striping spreads data over disks for speed. Mirroring copies it for safety. Parity stores an XOR of the data, so a lost block can be rebuilt at a lower cost. striping mirroring shadowing parity xor raid ideas vs difference"},
  {"id":"file-organizations","unit":4,"title":"Heap, sequential, hashing and clustering file organizations","text":"Heap files keep records in any order and sequential files keep them sorted. Hashing places them by a hash value, and clustering stores related records of several tables together. file organization heap sequential ordered hash multitable clustering vs difference"},
  {"id":"fixed-vs-variable-records","unit":4,"title":"Fixed-length and variable-length records","text":"Fixed-length records all have one size, so they are easy to find but waste space; variable-length records save space but need a slotted page to be found. fixed length variable length records slotted page vs difference"},
  {"id":"active-vs-passive-dictionary","unit":4,"title":"Active and passive data dictionary","text":"An active data dictionary is kept up to date by the DBMS itself; a passive one is kept by people, only for documentation. data dictionary system catalog metadata active passive vs difference"},
  {"id":"row-vs-column-storage","unit":4,"title":"Row-oriented and column-oriented storage","text":"Row storage keeps all the values of one record together; column storage keeps all the values of one attribute together. row oriented column oriented columnar storage analytics oltp olap vs difference"},
  {"id":"indexing-vs-hashing","unit":4,"title":"Ordered indexing and hashing","text":"An ordered index keeps keys sorted, so it handles both exact lookups and ranges. Hashing jumps straight to a bucket, so it is best for exact lookups only. index hashing ordered index hash index range query vs difference"},
  {"id":"dense-vs-sparse","unit":4,"title":"Dense and sparse indices","text":"A dense index has an entry for every search-key value; a sparse index has entries for only some values, one for each block. dense sparse index entry every search key block vs difference"},
  {"id":"clustering-vs-non-clustering","unit":4,"title":"Clustering (primary) and non-clustering (secondary) indices","text":"A clustering index is on the key the file is sorted by, so there is only one. A non-clustering index is on any other key, so there can be many and each must be dense. clustering non-clustering primary secondary index clustered vs difference"},
  {"id":"single-vs-multilevel-index","unit":4,"title":"Single-level and multilevel indices","text":"A single-level index is one sorted list of entries. A multilevel index adds a small sparse index on top of it, so a search reads far fewer blocks. single level multilevel index inner outer index b+ tree vs difference"},
  {"id":"btree-vs-bplus-tree","unit":4,"title":"B tree and B+ tree","text":"A B tree stores each key once, in any node. A B+ tree keeps every key in the linked leaves, so it is shorter and much better for range queries. b tree b+ tree b-tree index leaf linked fan-out vs difference"},
  {"id":"open-vs-closed-hashing","unit":4,"title":"Overflow chaining (closed hashing) and linear probing (open hashing)","text":"Overflow chaining puts extra records in overflow buckets linked to the full bucket; linear probing puts them in the next bucket that has space. open hashing closed hashing overflow chaining linear probing bucket overflow vs difference"},
  {"id":"static-vs-dynamic-hashing","unit":4,"title":"Static and dynamic hashing","text":"Static hashing has a fixed number of buckets, so a growing file overflows; dynamic (extendible) hashing splits buckets as the file grows. static dynamic extendible hashing bucket directory vs difference"},
  {"id":"join-algorithms","unit":4,"title":"Nested-loop, block nested-loop, indexed nested-loop, merge and hash joins","text":"The join algorithms find matching tuples in different ways. They test every pair, use an index, sort both inputs or hash both inputs into partitions. join algorithms nested loop block indexed merge sort hash join cost vs difference"},
  {"id":"heuristic-vs-cost-based","unit":4,"title":"Heuristic and cost-based optimization","text":"Heuristic optimization applies fixed rules to the query tree; cost-based optimization estimates the cost of many plans from statistics and picks the cheapest. query optimization heuristic rule based cost based statistics vs difference"}
];
